def read_file(remote_path, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0366000" if __import__("os").path.isdir("./environment_mix/0366000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_audit_store():
        # Create audit/usage store if absent. This is required so "every call moves the datastore".
        audits = _load("usage.json")
        if not isinstance(audits, dict) or "requests" not in audits or "counters" not in audits:
            audits = {
                "requests": [],
                "counters": {"total_calls": 0, "by_tool": {}, "by_status": {}},
                "rate_limit": {"window_seconds": 60, "max_requests": 600},
                "quota": {"max_requests_total": None},
            }
            _save("usage.json", audits)
        return audits

    def _audit_and_enforce(tool, params, status=None):
        audits = _ensure_audit_store()

        # Enforce rate limit and quota using persisted history.
        rl = audits.get("rate_limit") or {}
        window_seconds = rl.get("window_seconds", 60)
        max_requests = rl.get("max_requests", 600)
        quota = audits.get("quota") or {}
        max_total = quota.get("max_requests_total", None)

        now = datetime.datetime.utcnow()
        reqs = audits.get("requests", [])
        # Filter within window; tolerate malformed timestamps by ignoring them.
        cutoff = now - datetime.timedelta(seconds=int(window_seconds) if isinstance(window_seconds, int) else 60)
        in_window = 0
        for r in reqs:
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    in_window += 1

        if isinstance(max_requests, int) and max_requests >= 0 and in_window >= max_requests:
            # Record refused request as well.
            return audits, _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_seconds, max_requests=max_requests)

        if isinstance(max_total, int) and max_total >= 0:
            total_calls = (audits.get("counters") or {}).get("total_calls", 0)
            if isinstance(total_calls, int) and total_calls >= max_total:
                return audits, _err("QUOTA_EXCEEDED", "Quota exceeded", max_requests_total=max_total)

        return audits, None

    def _record(audits, tool, params, status, started_at):
        ended = time.time()
        latency_ms = int(round((ended - started_at) * 1000))
        row = {
            "id": f"req_{int(ended * 1000)}_{os.getpid()}",
            "timestamp": _now(),
            "tool": tool,
            "params": params,
            "status": status,
            "latency_ms": latency_ms,
        }
        audits["requests"] = audits.get("requests", [])
        audits["requests"].append(row)
        counters = audits.get("counters", {})
        counters["total_calls"] = int(counters.get("total_calls", 0) or 0) + 1
        by_tool = counters.get("by_tool") or {}
        by_tool[tool] = int(by_tool.get(tool, 0) or 0) + 1
        counters["by_tool"] = by_tool
        by_status = counters.get("by_status") or {}
        by_status[status] = int(by_status.get(status, 0) or 0) + 1
        counters["by_status"] = by_status
        audits["counters"] = counters
        _save("usage.json", audits)

    def _validate_remote_path(p):
        if p is None or not isinstance(p, str):
            return _err("VALIDATION_ERROR", "remote_path must be a string")
        if p.strip() == "":
            return _err("VALIDATION_ERROR", "remote_path is required")
        # Normalize separators and refuse traversal / absolute paths.
        if "\x00" in p:
            return _err("VALIDATION_ERROR", "remote_path contains invalid characters")
        norm = p.replace("\\", "/")
        if norm.startswith("/"):
            return _err("VALIDATION_ERROR", "remote_path must be workspace-relative")
        parts = [x for x in norm.split("/") if x not in ("", ".")]
        if any(x == ".." for x in parts):
            return _err("VALIDATION_ERROR", "remote_path attempts to traverse outside the workspace")
        # basic naming rules: disallow empty parts already handled; keep as-is.
        return None

    started = time.time()
    tool = "read_file"
    params_for_log = {"remote_path": remote_path}

    audits, blocked = _audit_and_enforce(tool, params_for_log)
    if blocked is not None:
        _record(audits, tool, params_for_log, "error", started)
        return blocked

    v = _validate_remote_path(remote_path)
    if v is not None:
        _record(audits, tool, params_for_log, "error", started)
        return v

    # Map "workspace-relative" path to local datastore.
    # The workspace root is /app/database/workspace. If it doesn't exist, treat as NOT_FOUND.
    workspace_root = os.path.join(_DB, "workspace")
    abs_path = os.path.normpath(os.path.join(workspace_root, remote_path.replace("\\", "/")))

    # Ensure abs_path is within workspace_root.
    try:
        common = os.path.commonpath([workspace_root, abs_path])
    except ValueError:
        _record(audits, tool, params_for_log, "error", started)
        return _err("VALIDATION_ERROR", "remote_path is invalid for this workspace")
    if common != workspace_root:
        _record(audits, tool, params_for_log, "error", started)
        return _err("VALIDATION_ERROR", "remote_path attempts to traverse outside the workspace")

    if not os.path.exists(abs_path):
        _record(audits, tool, params_for_log, "error", started)
        return _err("NOT_FOUND", "Path does not exist", remote_path=remote_path)

    if os.path.isdir(abs_path):
        _record(audits, tool, params_for_log, "error", started)
        return _err("VALIDATION_ERROR", "Path refers to a directory", remote_path=remote_path)

    if not os.path.isfile(abs_path):
        _record(audits, tool, params_for_log, "error", started)
        return _err("VALIDATION_ERROR", "Path is not a file", remote_path=remote_path)

    try:
        with open(abs_path, "r", encoding="utf-8") as f:
            text = f.read()
    except UnicodeDecodeError:
        _record(audits, tool, params_for_log, "error", started)
        return _err("VALIDATION_ERROR", "File is not valid UTF-8 text", remote_path=remote_path)
    except OSError:
        _record(audits, tool, params_for_log, "error", started)
        return _err("NOT_FOUND", "File could not be read", remote_path=remote_path)

    _record(audits, tool, params_for_log, "ok", started)
    return {
        "remote_path": remote_path,
        "content": text,
        "content_length": len(text),
    }

