def list_dir(remote_dir="workspace"):
    import os
    def _abs(remote_path):
        root = os.path.join(_DB, "workspace")
        p = str(remote_path)
        if p.startswith(_DB): return p
        if p.startswith("workspace"): return os.path.join(_DB, p)
        return os.path.join(root, p.lstrip("/"))
    path = _abs(remote_dir)
    if not os.path.isdir(path):
        return {"error": f"not a directory: {remote_dir}"}
    out = []
    for dp, dn, fn in os.walk(path):
        for f in fn:
            rel = os.path.relpath(os.path.join(dp, f), os.path.join(_DB))
            out.append(rel)
    return sorted(out)

