def write_file(remote_path, content):
    import os
    def _abs(remote_path):
        root = os.path.join(_DB, "workspace")
        p = str(remote_path)
        if p.startswith(_DB): return p
        if p.startswith("workspace"): return os.path.join(_DB, p)
        return os.path.join(root, p.lstrip("/"))
    path = _abs(remote_path)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(content if isinstance(content, str) else str(content))
    return {"written": True, "path": remote_path, "bytes": len(content or "")}

